package v1beta1

import (
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
)

// InfisicalAuth is the Schema for the InfisicalAuth API.
// +kubebuilder:object:root=true
// +kubebuilder:subresource:status
// +kubebuilder:printcolumn:name="Connection",type=string,JSONPath=`.spec.infisicalConnectionRef.name`
// +kubebuilder:printcolumn:name="Method",type=string,JSONPath=`.spec.method`
// +kubebuilder:printcolumn:name="Age",type=date,JSONPath=`.metadata.creationTimestamp`
// +kubebuilder:printcolumn:name="Ready",type=string,JSONPath=`.status.conditions[?(@.type=="secrets.infisical.com/IsReady")].status`
type InfisicalAuth struct {
	metav1.TypeMeta   `json:",inline"`
	metav1.ObjectMeta `json:"metadata,omitempty"`

	Spec   InfisicalAuthSpec   `json:"spec,omitempty"`
	Status InfisicalAuthStatus `json:"status,omitempty"`
}

type InfisicalAuthSpec struct {
	// +kubebuilder:validation:Optional
	InfisicalConnectionRef NamespacedName `json:"infisicalConnectionRef,omitempty"`

	// +kubebuilder:validation:Required
	Method InfisicalAuthMethod `json:"method"`

	// +kubebuilder:validation:Optional
	Universal *UniversalAuthConfig `json:"universal,omitempty"`

	// +kubebuilder:validation:Optional
	Kubernetes *KubernetesAuthConfig `json:"kubernetes,omitempty"`

	// +kubebuilder:validation:Optional
	AWSIam *AWSIamAuthConfig `json:"awsIam,omitempty"`

	// +kubebuilder:validation:Optional
	Azure *AzureAuthConfig `json:"azure,omitempty"`

	// +kubebuilder:validation:Optional
	GCPIdToken *GCPIdTokenAuthConfig `json:"gcpIdToken,omitempty"`

	// +kubebuilder:validation:Optional
	GCPIam *GCPIamAuthConfig `json:"gcpIam,omitempty"`

	// +kubebuilder:validation:Optional
	LDAP *LDAPAuthConfig `json:"ldap,omitempty"`
}

type UniversalAuthConfig struct {
	// +kubebuilder:validation:Required
	ClientIdRef SecretReference `json:"clientIdRef"`

	// +kubebuilder:validation:Required
	ClientSecretRef SecretReference `json:"clientSecretRef"`
}

type KubernetesAuthConfig struct {
	// +kubebuilder:validation:Required
	IdentityIDRef SecretReference `json:"identityIdRef"`

	// +kubebuilder:validation:Required
	ServiceAccountRef NamespacedName `json:"serviceAccountRef"`

	// The audiences to use for the service account token. This is only relevant if `autoCreateServiceAccountToken` is true.
	// +kubebuilder:validation:Optional
	ServiceAccountTokenAudiences []string `json:"serviceAccountTokenAudiences"`
}

type AWSIamAuthConfig struct {
	// +kubebuilder:validation:Required
	IdentityIDRef SecretReference `json:"identityIdRef"`
}

type AzureAuthConfig struct {
	// +kubebuilder:validation:Required
	IdentityIDRef SecretReference `json:"identityIdRef"`

	// +kubebuilder:validation:Optional
	Resource string `json:"resource"`
}

type GCPIdTokenAuthConfig struct {
	// +kubebuilder:validation:Required
	IdentityIDRef SecretReference `json:"identityIdRef"`
}

type GCPIamAuthConfig struct {
	// +kubebuilder:validation:Required
	IdentityIDRef SecretReference `json:"identityIdRef"`

	// +kubebuilder:validation:Required
	ServiceAccountKeyFilePath string `json:"serviceAccountKeyFilePath"`
}

type LDAPAuthConfig struct {
	// +kubebuilder:validation:Required
	UsernameRef SecretReference `json:"usernameRef"`

	// +kubebuilder:validation:Required
	PasswordRef SecretReference `json:"passwordRef"`

	// +kubebuilder:validation:Required
	IdentityIDRef SecretReference `json:"identityIdRef"`
}

type NamespacedName struct {
	// +kubebuilder:validation:Required
	Name string `json:"name"`

	// +kubebuilder:validation:Required
	Namespace string `json:"namespace"`
}

// InfisicalAuthStatus defines the observed state of InfisicalAuth
type InfisicalAuthStatus struct {
	Conditions []metav1.Condition `json:"conditions"`
}

// +kubebuilder:validation:Enum=universal;kubernetes;aws-iam;azure;gcp-id-token;gcp-iam;ldap
type InfisicalAuthMethod string

const (
	AWSIamAuth     InfisicalAuthMethod = "aws-iam"
	AzureAuth      InfisicalAuthMethod = "azure"
	GCPIamAuth     InfisicalAuthMethod = "gcp-iam"
	GCPIdTokenAuth InfisicalAuthMethod = "gcp-id-token"
	KubernetesAuth InfisicalAuthMethod = "kubernetes"
	LDAPAuth       InfisicalAuthMethod = "ldap"
	UniversalAuth  InfisicalAuthMethod = "universal"
)

// InfisicalAuthList contains a list of InfisicalAuth.
// +kubebuilder:object:root=true
type InfisicalAuthList struct {
	metav1.TypeMeta `json:",inline"`
	metav1.ListMeta `json:"metadata,omitempty"`
	Items           []InfisicalAuth `json:"items"`
}

func init() {
	SchemeBuilder.Register(&InfisicalAuth{}, &InfisicalAuthList{})
}

package auth

import (
	"context"
	"fmt"

	"github.com/Infisical/infisical/k8-operator/api/v1beta1"
	"github.com/Infisical/infisical/k8-operator/internal/model"
	"github.com/Infisical/infisical/k8-operator/internal/util"
	infisicalSdk "github.com/infisical/go-sdk"
	authenticationv1 "k8s.io/api/authentication/v1"
	corev1 "k8s.io/api/core/v1"
	"k8s.io/utils/ptr"
	"sigs.k8s.io/controller-runtime/pkg/client"
)

type kubernetesAuth struct {
	client          client.Client
	namespaceScoped bool
}

func NewKubernetesAuth(c client.Client, namespaceScoped bool) InfisicalAuthStrategy {
	return &kubernetesAuth{client: c, namespaceScoped: namespaceScoped}
}

func (k *kubernetesAuth) Validate(ctx context.Context, auth *v1beta1.InfisicalAuth) error {
	if auth == nil {
		return model.ErrInvalidAuthObject
	}

	k8s := auth.Spec.Kubernetes
	if k8s == nil {
		return fmt.Errorf("auth method is %q but .spec.kubernetes is not set", v1beta1.KubernetesAuth)
	}

	if k8s.ServiceAccountRef.Name == "" || k8s.ServiceAccountRef.Namespace == "" {
		return fmt.Errorf(`"serviceAccountRef.name" and "serviceAccountRef.namespace" are required when "autoCreateServiceAccountToken" is enabled`)
	}

	return nil
}

func (k *kubernetesAuth) Authenticate(
	ctx context.Context,
	connection *model.InfisicalConnection,
	auth *v1beta1.InfisicalAuth,
) (*model.AuthenticationResult, error) {
	if connection == nil {
		return nil, model.ErrInvalidConnectionObject
	}

	if auth == nil {
		return nil, model.ErrInvalidAuthObject
	}

	if auth.Spec.Kubernetes == nil {
		return nil, fmt.Errorf("%w: spec.kubernetes is nil", model.ErrInvalidAuthObject)
	}

	identityID, err := util.ResolveSecretReference(ctx, k.client, auth.Spec.Kubernetes.IdentityIDRef, ".spec.kubernetes.identityIdRef")
	if err != nil {
		return nil, err
	}

	serviceAccount, err := k.getServiceAccount(ctx, auth)
	if err != nil {
		return nil, err
	}

	saToken, err := k.getServiceAccountToken(ctx, auth, serviceAccount)
	if err != nil {
		return nil, err
	}

	sdkClient := infisicalSdk.NewInfisicalClient(ctx, infisicalSdk.Config{
		SiteUrl:          connection.Host,
		CaCertificate:    connection.CaCertificate,
		AutoTokenRefresh: infisicalSdk.BoolPtr(false),
	})

	cred, err := sdkClient.Auth().KubernetesRawServiceAccountTokenLogin(string(identityID), saToken)
	if err != nil {
		return nil, fmt.Errorf("unable to authenticate with Kubernetes: %w", err)
	}

	return &model.AuthenticationResult{MachineIdentity: cred, SdkClient: sdkClient}, nil
}

func (k *kubernetesAuth) getServiceAccount(ctx context.Context, auth *v1beta1.InfisicalAuth) (*corev1.ServiceAccount, error) {
	k8s := auth.Spec.Kubernetes
	key := client.ObjectKey{
		Namespace: k8s.ServiceAccountRef.Namespace,
		Name:      k8s.ServiceAccountRef.Name,
	}

	sa := &corev1.ServiceAccount{}
	if err := k.client.Get(ctx, key, sa); err != nil {
		if util.IsNamespaceScopedError(err, k.namespaceScoped) {
			return nil, model.NewNamespaceScopedError(err, "service account")
		}
		return nil, fmt.Errorf("unable to get service account: %w", err)
	}

	return sa, nil
}

func (k *kubernetesAuth) getServiceAccountToken(ctx context.Context, auth *v1beta1.InfisicalAuth, serviceAccount *corev1.ServiceAccount) (string, error) {
	k8s := auth.Spec.Kubernetes

	restClient, err := util.GetRestClientFromClient()
	if err != nil {
		return "", fmt.Errorf("unable to get REST client: %w", err)
	}

	tokenRequest := &authenticationv1.TokenRequest{
		Spec: authenticationv1.TokenRequestSpec{
			ExpirationSeconds: ptr.To[int64](600),
		},
	}

	if len(k8s.ServiceAccountTokenAudiences) > 0 {
		tokenRequest.Spec.Audiences = k8s.ServiceAccountTokenAudiences
	}

	result := &authenticationv1.TokenRequest{}
	err = restClient.
		Post().
		Namespace(serviceAccount.Namespace).
		Resource("serviceaccounts").
		Name(serviceAccount.Name).
		SubResource("token").
		Body(tokenRequest).
		Do(ctx).
		Into(result)
	if err != nil {
		return "", fmt.Errorf("unable to create service account token: %w", err)
	}

	return result.Status.Token, nil
}

